// Localized destination content. Falls back to English (from data.js) if a
// destination or language is missing here. "guide" is a single condensed
// narration paragraph (landscape + daily life + culture + a practical note),
// played as one track for non-English languages.
const DESTINATION_TRANSLATIONS = {
  es: {
    kyoto: { country:"Japón", teaser:"Una ciudad que aún vive al ritmo de sandalias de madera y campanas de templo.", guide:"Kioto se asienta entre colinas cubiertas de más de mil templos y santuarios, con el río Kamo cruzando la ciudad. La gente se mueve en bicicleta entre casas centenarias y tiendas familiares que abren al amanecer. Aquí se perfeccionaron la ceremonia del té y el teatro Noh, y aún puedes aprenderlos con un maestro real. Lleva efectivo: muchos templos y comercios pequeños no aceptan tarjeta." },
    marrakech: { country:"Marruecos", teaser:"La medina nunca queda realmente en silencio, solo cambia lo que vende.", guide:"Marrakech se extiende entre la llanura fértil y las montañas del Atlas, con una medina de tono terracota protegido por ley. La vida familiar gira en torno a los patios de las casas riad, y el té de menta es casi un ritual sagrado de hospitalidad. La plaza Jemaa el-Fnaa se transforma cada noche en un mercado al aire libre. Regatear en los zocos es la conversación esperada, no una grosería." },
    cusco: { country:"Perú", teaser:"Una capital inca donde la piedra antigua todavía sostiene el peso de la ciudad.", guide:"Cusco se alza a más de 3.400 metros en los Andes, con muros incas de piedra ajustada sirviendo de base a edificios coloniales. El quechua se habla junto al español, y la hoja de coca es parte normal de la vida diaria, no una novedad turística. Cada junio, el Inti Raymi recrea una ceremonia inca ante multitudes. Tómate uno o dos días para aclimatarte antes de caminar mucho." },
    "cape-town": { country:"Sudáfrica", teaser:"Una ciudad donde dos océanos, una montaña y una historia compleja se encuentran a la vez.", guide:"Ciudad del Cabo se asienta bajo la Montaña de la Mesa, entre dos corrientes oceánicas que dejan playas de temperaturas muy distintas. El braai, una parrilla lenta, es casi un ritual semanal entre vecinos y familia. Los recorridos por los townships, dirigidos por sus propios residentes, muestran una versión más honesta de la ciudad que solo el paseo marítimo. El clima cambia rápido: lleva capas de abrigo." },
    reykjavik: { country:"Islandia", teaser:"Una capital tan pequeña que el alcalde podría estar en el carril de al lado en la piscina.", guide:"Reikiavik funciona con agua geotérmica que calienta hasta las piscinas públicas, verdadero centro social de la ciudad. En verano el sol casi no se pone, y en invierno casi no sale. Las sagas islandesas, historias centenarias, todavía se leen y se citan con frecuencia. El agua del grifo es de las más limpias del mundo, y alquilar un coche abre mucho más que la propia capital." },
    bali: { country:"Indonesia (Bali)", teaser:"Un pueblo donde una ceremonia en el templo puede desviar el tráfico sin que a nadie le importe.", guide:"Ubud está rodeado de arrozales en terraza regados por el antiguo sistema subak, gestionado en cooperativa por los agricultores. Cada mañana aparecen ofrendas frescas de flores y arroz en las puertas de las casas. Las ceremonias, desde cremaciones hasta aniversarios de templos, pueden cerrar una calle sin previo aviso. Lleva un sarong, es obligatorio para entrar en la mayoría de los templos." },
    hanoi: { country:"Vietnam", teaser:"Una ciudad que desayuna en pequeños taburetes de plástico, de pie si hace falta.", guide:"Hanói rodea el lago Hoan Kiem, con un Casco Antiguo cuyas 36 calles llevan aún el nombre del oficio que allí se vendía. Las motos superan ampliamente a los coches, y cruzar la calle significa caminar con paso firme y constante. El culto a los antepasados se ve en pequeños altares dentro de casas y tiendas. La comida callejera en taburete suele ser mejor que el restaurante de al lado." },
    jaipur: { country:"India", teaser:"Toda una ciudad antigua pintada del mismo tono rosa, por decreto real.", guide:"Jaipur bordea el desierto de Thar, con fuertes como Amber sobre las colinas y un casco antiguo pintado de terracota rosado desde 1876 por decreto real, aún vigente. Los bazares se organizan por oficio: joyería, textiles, especias, cada uno con talleres familiares de generaciones. Rajastán mantiene una cultura real viva, con festivales como Teej llenando las calles. Regatear con firmeza en los bazares es completamente normal." },
    istanbul: { country:"Turquía", teaser:"La única ciudad donde puedes desayunar en Europa y almorzar en Asia.", guide:"Estambul se divide físicamente entre Europa y Asia por el Bósforo, y cruzar en ferry es un desplazamiento diario más, no una excursión turística. El té se sirve constantemente en pequeños vasos con forma de tulipán. La ciudad conserva capas bizantinas y otomanas, a veces dentro de un mismo edificio como Santa Sofía. Un paseo en ferry por el Bósforo es de lo mejor y más barato que puedes hacer." },
    seoul: { country:"Corea del Sur", teaser:"Palacios de quinientos años conviven a pocas calles de tiendas abiertas las veinticuatro horas.", guide:"Seúl se extiende junto al río Han, rodeada de montañas cercanas incluso al centro urbano. Las tiendas de conveniencia funcionan como cafeterías nocturnas informales, muy usadas por estudiantes y oficinistas. El respeto por la jerarquía, herencia confuciana, marca aún la forma de hablar. El metro es rápido, barato y prácticamente universal; la tarjeta T-money sirve para casi todo." },
    "chiang-mai": { country:"Tailandia", teaser:"Más de trescientos templos dentro de una ciudad que aún se siente tranquila.", guide:"Chiang Mai descansa en un valle montañoso del norte de Tailandia, más fresco y verde que Bangkok, con el templo dorado de Doi Suthep visible desde la ciudad. La vida transcurre más despacio, con monjes recibiendo limosna cada mañana. La cultura Lanna, distinta del centro del país, se ve en templos y dialecto propios. Revisa la temporada de quemas agrícolas, entre febrero y abril, antes de reservar." },
    lisbon: { country:"Portugal", teaser:"Una ciudad de siete colinas donde cada viaje en tranvía es también un mirador.", guide:"Lisboa se construye sobre colinas empinadas junto al estuario del Tajo, con tranvías amarillos históricos que aún sirven de transporte real. Los pastéis de nata y el café fuerte son un hábito diario, no solo turístico. El fado, música melancólica reconocida por la UNESCO, se canta en clubes pequeños donde se espera silencio. Muchos miradores gratuitos superan a las atracciones de pago." },
    prague: { country:"República Checa", teaser:"Un complejo de castillo tan grande que podría ser su propio pueblo, y sigue en uso diario.", guide:"Praga se extiende junto al río Vltava, bajo uno de los mayores complejos de castillo antiguo del mundo, aún sede del presidente checo. La ciudad escapó de los bombardeos de la Segunda Guerra Mundial, por lo que su casco gótico y barroco se conserva casi intacto. La cerveza es más barata que el agua embotellada en muchos bares. Las mañanas en el casco antiguo son mucho más tranquilas que el resto del día." },
    athens: { country:"Grecia", teaser:"Una colina de tres mil años se alza en medio de una ciudad moderna en pleno funcionamiento.", guide:"Atenas se extiende en una cuenca rodeada de montañas, con la Acrópolis visible desde casi cualquier barrio. Las cenas empiezan tarde, casi nunca antes de las nueve de la noche, y los cafés se usan para conversaciones largas. La Pascua ortodoxa se celebra con más fuerza que la Navidad. Los sitios antiguos son mucho menos concurridos a primera hora de la mañana." },
    edinburgh: { country:"Escocia, Reino Unido", teaser:"Un castillo sobre un volcán vigila una ciudad construida sobre calles subterráneas ocultas.", guide:"Edimburgo se alza sobre un antiguo volcán, con callejones estrechos que a veces esconden calles enteras enterradas bajo la ciudad. El clima cambia rápido, así que las capas de ropa son esenciales todo el año. El Festival Fringe de agosto convierte la ciudad entera en el mayor festival de artes del mundo. Reserva alojamiento con meses de antelación si viajas en temporada de festival." },
    zanzibar: { country:"Zanzíbar, Tanzania", teaser:"Un puerto comercial donde puertas de madera talladas anunciaban antaño la riqueza de una familia.", guide:"Stone Town se asienta en la costa de Zanzíbar, un laberinto de piedra coralina construido durante siglos como centro comercial del Índico. La cultura suajili mezcla influencias africanas, árabes, persas e indias visibles en comida y arquitectura. Las puertas talladas, de estilo árabe o indio, aún indican el estatus histórico de una familia. El vestido modesto es apropiado en esta comunidad de mayoría musulmana." },
    cairo: { country:"Egipto", teaser:"Pirámides milenarias al borde literal de una megaciudad de veinte millones de personas.", guide:"El Cairo se extiende junto al Nilo, con las pirámides de Guiza hoy al borde mismo de la ciudad. El tráfico es denso y los cafés de té y shisha funcionan como verdaderos centros sociales diarios. El Ramadán transforma por completo el horario de la ciudad, tranquila de día y animada tras la puesta de sol. Visitar las pirámides a primera hora evita el calor y las multitudes." },
    accra: { country:"Ghana", teaser:"Una costa de fuertes centenarios junto a algunos de los mercados más vivos de África Occidental.", guide:"Accra se asienta en el golfo de Guinea, con antiguos fuertes coloniales aún en pie junto al mar. El mercado de Makola es una parada diaria real para los habitantes, denso en telas y alimentos. La tela kente, tejida con patrones de significado propio, se sigue usando en ocasiones importantes. Un saludo antes de negociar se considera una cortesía social importante." },
    oaxaca: { country:"México", teaser:"Un valle donde dieciséis grupos indígenas todavía dan forma a la vida diaria.", guide:"Oaxaca se sitúa en un valle rodeado de montañas, cerca del sitio zapoteca de Monte Albán. Dieciséis grupos indígenas conservan sus propias lenguas junto al español. El Día de Muertos se vive aquí con especial profundidad, con altares familiares y veladas en los cementerios. Las catas de mezcal en pequeñas palenques fuera de la ciudad son más auténticas que los bares del centro." },
    "new-orleans": { country:"Estados Unidos", teaser:"Una ciudad que entierra a sus muertos sobre el suelo porque el nivel freático no permite otra cosa.", guide:"Nueva Orleans se encuentra mayormente bajo el nivel del mar, entre el río Misisipi y el lago Pontchartrain, protegida por diques tras el huracán Katrina. La música en vivo se derrama a diario en la calle Frenchmen, no es un evento especial. Los funerales de jazz, con banda de metales, siguen siendo una tradición real. La temporada de huracanes va de junio a noviembre, conviene revisarla antes de reservar." },
    havana: { country:"Cuba", teaser:"Una ciudad donde los autos estadounidenses de los años cincuenta siguen siendo transporte diario, por necesidad.", guide:"La Habana bordea el estrecho de Florida, con el malecón como principal punto de encuentro social cada tarde. Décadas de restricciones han mantenido en marcha, con reparaciones ingeniosas, los autos clásicos de los años cincuenta. El son cubano y la salsa nacieron aquí y se tocan en vivo en clubes pequeños cada noche. El efectivo y el wifi por tarjetas en puntos públicos siguen siendo la norma." },
    rio: { country:"Brasil", teaser:"Montañas, selva y playa caben dentro de los límites de la ciudad, no fuera de ella.", guide:"Río de Janeiro se encaja entre picos de granito, selva atlántica y playas, todo dentro de los límites urbanos. La vida de playa es un hábito diario real, no solo vacacional, en Copacabana e Ipanema. El Carnaval implica todo un año de ensayos en las escuelas de samba de cada barrio. Reserva los recorridos por favelas con operadores comunitarios, no con empresas externas." },
    cartagena: { country:"Colombia", teaser:"Una ciudad colonial amurallada construida para resistir siglos de ataques piratas.", guide:"Cartagena se asienta en la costa caribeña, con murallas de piedra que aún rodean el casco antiguo, construidas contra ataques piratas. Las palenqueras venden fruta tropical con bandejas en la cabeza, herencia del cercano pueblo de San Basilio de Palenque. La champeta, música afrocaribeña, anima las noches reales de la ciudad. El calor del mediodía es intenso: mejor caminar de mañana o al atardecer." },
    "buenos-aires": { country:"Argentina", teaser:"Una ciudad que cena a las diez de la noche y lo considera completamente normal.", guide:"Buenos Aires se extiende junto al ancho río de la Plata, con barrios de marcada influencia europea. La cena empieza realmente a las diez, y el asado es casi un ritual semanal familiar. El mate, compartido entre amigos con una bombilla, es un hábito constante durante todo el día. El tango nació aquí y se baila de verdad en las milongas, más allá de los espectáculos para turistas." },
    queenstown: { country:"Nueva Zelanda", teaser:"Un pequeño pueblo alpino que inventó el puenting comercial en un puente histórico.", guide:"Queenstown se asienta junto al lago Wakatipu, rodeado por la cordillera de los Remarkables, en la isla sur de Nueva Zelanda. Es un pueblo pequeño donde la vida diaria gira en torno al turismo de aventura, senderismo en verano y esquí en invierno. El puenting comercial se inventó aquí, en el puente Kawarau, que sigue en funcionamiento. El clima cambia rápido en las montañas: lleva siempre capas de abrigo." },
    "byron-bay": { country:"Australia", teaser:"El punto más oriental de la Australia continental, y funciona según el horario de las olas.", guide:"Byron Bay marca el punto más oriental de Australia continental, con un faro desde donde a veces se ven ballenas migrando. Las condiciones del surf marcan literalmente el horario diario de gran parte del pueblo. La cultura de bienestar y mercados orgánicos es genuina, arraigada desde hace décadas, no solo marketing. La protección solar importa más de lo esperado: el índice UV es alto." },
    petra: { country:"Jordania", teaser:"Toda una ciudad antigua tallada directamente en muros de cañón color rosa.", guide:"Petra se esconde en un cañón desértico, alcanzado por un desfiladero llamado el Siq, donde los nabateos tallaron fachadas en la roca arenisca hace más de dos mil años. Comunidades beduinas locales, algunas descendientes de quienes vivieron dentro de Petra, aún guían a los visitantes. Recorrer todo el sitio toma casi un día completo, así que el calzado cómodo es esencial." },
    muscat: { country:"Omán", teaser:"Una capital que exige que cada edificio nuevo mantenga los mismos tonos blancos y arena.", guide:"Mascate se extiende junto al golfo de Omán, entre montañas y costa, con fuertes portugueses antiguos aún en pie. Las normas de construcción exigen edificios bajos en tonos blancos o arena, dando a la ciudad un aspecto uniforme. El incienso se quema a diario en casas y tiendas, herencia del antiguo comercio de incienso omaní. El vestido modesto se espera y se aprecia en todos los espacios públicos." },
    samarkand: { country:"Uzbekistán", teaser:"Un cruce de la Ruta de la Seda donde cúpulas turquesa llevan seis siglos en pie.", guide:"Samarcanda ocupa una llanura fértil de Asia Central, cruce histórico de la Ruta de la Seda entre China, Persia y Europa. El Registán, plaza rodeada de tres madrasas cubiertas de azulejos turquesa, lleva más de seiscientos años en el centro de la ciudad. El pan redondo, llamado non, se trata con auténtico respeto, nunca se tira ni se coloca boca abajo. Ver el Registán iluminado de noche es una experiencia distinta y muy recomendable." }
  },
  fr: {
    kyoto: { country:"Japon", teaser:"Une ville qui vit encore au rythme des sandales de bois et des cloches de temple.", guide:"Kyoto s'étend parmi des collines abritant plus de mille temples et sanctuaires, traversée par la rivière Kamo. Les habitants se déplacent à vélo entre maisons centenaires et petites échoppes familiales ouvertes dès l'aube. La cérémonie du thé et le théâtre Nô y ont été perfectionnés, et s'apprennent encore auprès de vrais maîtres. Prévoyez des espèces : nombre de temples et petits commerces n'acceptent pas la carte." },
    marrakech: { country:"Maroc", teaser:"La médina ne se tait jamais vraiment, elle change simplement ce qu'elle vend.", guide:"Marrakech s'étend entre plaine fertile et montagnes de l'Atlas, avec une médina couleur terre cuite protégée par la loi. La vie familiale s'organise autour des cours des maisons riad, et le thé à la menthe est un rituel d'hospitalité quasi sacré. La place Jemaa el-Fnaa se transforme chaque soir en marché à ciel ouvert. Marchander dans les souks est la conversation attendue, pas une impolitesse." },
    cusco: { country:"Pérou", teaser:"Une capitale inca où les vieilles pierres soutiennent encore le poids de la ville.", guide:"Cusco s'élève à plus de 3 400 mètres dans les Andes, ses murs incas aux pierres parfaitement ajustées servant de base à des bâtiments coloniaux. Le quechua se parle encore aux côtés de l'espagnol, et la feuille de coca fait partie de la vie quotidienne, pas seulement des touristes. Chaque juin, l'Inti Raymi recrée une cérémonie inca devant les foules. Prenez un jour ou deux pour vous acclimater avant de beaucoup marcher." },
    "cape-town": { country:"Afrique du Sud", teaser:"Une ville où deux océans, une montagne et une histoire complexe se rencontrent à la fois.", guide:"Le Cap se love sous la Montagne de la Table, entre deux courants océaniques qui rendent les plages très inégales en température. Le braai, barbecue lent, est presque un rituel hebdomadaire entre voisins et famille. Les visites de townships, menées par leurs propres habitants, montrent une facette plus honnête de la ville que le front de mer seul. Le temps change vite : prévoyez des couches." },
    reykjavik: { country:"Islande", teaser:"Une capitale si petite que le maire pourrait nager dans le couloir voisin à la piscine.", guide:"Reykjavik fonctionne à l'eau géothermique, qui chauffe jusqu'aux piscines publiques, véritable centre social de la ville. L'été, le soleil ne se couche presque pas, et l'hiver, il ne se lève presque pas. Les sagas islandaises, récits centenaires, sont encore lues et citées couramment. L'eau du robinet compte parmi les plus pures au monde, et louer une voiture ouvre bien plus que la seule capitale." },
    bali: { country:"Indonésie (Bali)", teaser:"Une ville où une cérémonie au temple peut dévier la circulation sans que personne ne s'en formalise.", guide:"Ubud est entourée de rizières en terrasses irriguées par l'ancien système coopératif subak, géré par les agriculteurs eux-mêmes. Chaque matin, de nouvelles offrandes de fleurs et de riz apparaissent devant les maisons. Les cérémonies, des crémations aux anniversaires de temples, peuvent fermer une rue sans préavis. Un sarong est obligatoire pour entrer dans la plupart des temples." },
    hanoi: { country:"Vietnam", teaser:"Une ville qui prend son petit-déjeuner sur de minuscules tabourets en plastique, debout s'il le faut.", guide:"Hanoï s'enroule autour du lac Hoan Kiem, son Vieux Quartier aux 36 rues encore nommées d'après le métier qui s'y pratiquait. Les scooters dépassent largement les voitures, et traverser la rue se fait d'un pas régulier et prévisible. Le culte des ancêtres se voit sur de petits autels dans les maisons et les commerces. La street food sur tabouret vaut souvent mieux que le restaurant d'à côté." },
    jaipur: { country:"Inde", teaser:"Toute une vieille ville peinte de la même teinte rose, par décret royal.", guide:"Jaipur borde le désert du Thar, avec des forts comme Amber sur les collines et une vieille ville peinte en rose terre cuite depuis 1876 par décret royal, toujours en vigueur. Les bazars s'organisent par métier : bijoux, textiles, épices, chacun tenu par des familles depuis des générations. Le Rajasthan conserve une culture royale bien vivante, avec des festivals comme Teej envahissant les rues. Marchander fermement dans les bazars est tout à fait normal." },
    istanbul: { country:"Turquie", teaser:"La seule ville où l'on peut prendre son petit-déjeuner en Europe et déjeuner en Asie.", guide:"Istanbul est physiquement partagée entre Europe et Asie par le Bosphore, et prendre le ferry est un trajet quotidien, pas une excursion touristique. Le thé se sert sans cesse dans de petits verres en forme de tulipe. La ville conserve des strates byzantines et ottomanes, parfois dans un même bâtiment comme Sainte-Sophie. Une traversée du Bosphore en ferry est l'une des meilleures choses à faire, et l'une des moins chères." },
    seoul: { country:"Corée du Sud", teaser:"Des palais vieux de cinq cents ans côtoient des quartiers ouverts vingt-quatre heures sur vingt-quatre.", guide:"Séoul s'étend le long du fleuve Han, entourée de montagnes proches même du centre-ville dense. Les supérettes servent de cafés nocturnes informels, très utilisées par étudiants et employés. Le respect confucéen de la hiérarchie marque encore la façon de s'adresser aux autres. Le métro est rapide, bon marché et quasi universel ; la carte T-money sert à presque tout." },
    "chiang-mai": { country:"Thaïlande", teaser:"Plus de trois cents temples dans une ville qui garde encore un rythme paisible.", guide:"Chiang Mai repose dans une vallée montagneuse du nord de la Thaïlande, plus fraîche et verte que Bangkok, avec le temple doré du Doi Suthep visible depuis la ville. La vie y est nettement plus lente, avec l'aumône aux moines chaque matin. La culture Lanna, distincte du centre du pays, se retrouve dans l'architecture et le dialecte locaux. Vérifiez la saison des brûlis agricoles, de février à avril, avant de réserver." },
    lisbon: { country:"Portugal", teaser:"Une ville aux sept collines où chaque trajet de tram est aussi un point de vue.", guide:"Lisbonne est bâtie sur des collines abruptes au-dessus de l'estuaire du Tage, ses tramways jaunes historiques servant encore de vrais transports en commun. Les pastéis de nata et le café fort sont une habitude quotidienne, pas seulement touristique. Le fado, musique mélancolique reconnue par l'UNESCO, se chante dans de petits clubs où le silence est de rigueur. De nombreux miradouros gratuits valent mieux que les attractions payantes." },
    prague: { country:"République tchèque", teaser:"Un complexe de château assez vaste pour être sa propre petite ville, encore en usage quotidien.", guide:"Prague s'étend le long de la Vltava, dominée par l'un des plus grands complexes de château ancien au monde, toujours siège du président tchèque. La ville a largement échappé aux bombardements de la Seconde Guerre mondiale, préservant son centre gothique et baroque presque intact. La bière y coûte souvent moins cher que l'eau en bouteille. Les matinées dans la vieille ville sont bien plus calmes que le reste de la journée." },
    athens: { country:"Grèce", teaser:"Une colline vieille de trois mille ans se dresse au cœur d'une ville moderne bien vivante.", guide:"Athènes s'étend dans un bassin cerné de montagnes, l'Acropole visible depuis presque tous les quartiers. Les dîners commencent tard, rarement avant vingt et une heures, et les cafés servent à de longues conversations. Pâques orthodoxe se fête avec plus d'éclat que Noël. Les sites antiques sont bien moins fréquentés tôt le matin." },
    edinburgh: { country:"Écosse, Royaume-Uni", teaser:"Un château perché sur un volcan surplombe une ville bâtie sur des rues souterraines cachées.", guide:"Édimbourg se dresse sur un ancien volcan, ses ruelles étroites cachant parfois des rues entières enterrées sous la ville. Le temps change vite, les couches de vêtements sont essentielles toute l'année. Le Festival Fringe d'août transforme la ville entière en plus grand festival des arts au monde. Réservez un hébergement plusieurs mois à l'avance si vous voyagez en période de festival." },
    zanzibar: { country:"Zanzibar, Tanzanie", teaser:"Un port marchand où des portes en bois sculptées signalaient autrefois la richesse d'une famille.", guide:"Stone Town se dresse sur la côte de Zanzibar, un dédale de pierre corallienne bâti pendant des siècles comme carrefour commercial de l'océan Indien. La culture swahilie mêle influences africaines, arabes, perses et indiennes visibles dans la cuisine et l'architecture. Les portes sculptées, de style arabe ou indien, indiquent encore le statut historique d'une famille. Une tenue modeste est appréciée dans cette communauté majoritairement musulmane." },
    cairo: { country:"Égypte", teaser:"Des pyramides millénaires à la lisière littérale d'une mégapole de vingt millions d'habitants.", guide:"Le Caire s'étend le long du Nil, les pyramides de Gizeh se trouvant aujourd'hui en bordure même de la ville. La circulation y est dense, et les cafés à thé et chicha servent de véritables lieux de sociabilité quotidienne. Le ramadan transforme entièrement le rythme de la ville, calme le jour et animée après la rupture du jeûne. Visiter les pyramides à l'ouverture évite chaleur et foule." },
    accra: { country:"Ghana", teaser:"Un littoral de forts centenaires côtoie certains des marchés les plus vivants d'Afrique de l'Ouest.", guide:"Accra borde le golfe de Guinée, d'anciens forts coloniaux se dressant encore le long de la côte. Le marché Makola est une vraie destination quotidienne pour les habitants, dense en tissus et en nourriture. Le tissu kente, tissé selon des motifs porteurs de sens, se porte encore lors d'occasions importantes. Un salut avant de négocier est considéré comme une politesse sociale importante." },
    oaxaca: { country:"Mexique", teaser:"Une vallée où seize groupes indigènes façonnent encore la vie quotidienne.", guide:"Oaxaca se niche dans une vallée cernée de montagnes, près du site zapotèque de Monte Alban. Seize groupes indigènes distincts conservent leurs propres langues aux côtés de l'espagnol. Le Jour des Morts y est vécu avec une profondeur particulière, entre autels familiaux et veillées au cimetière. Les dégustations de mezcal dans les petits palenques hors de la ville sont plus authentiques que les bars du centre." },
    "new-orleans": { country:"États-Unis", teaser:"Une ville qui enterre ses morts au-dessus du sol car la nappe phréatique ne permet rien d'autre.", guide:"La Nouvelle-Orléans se trouve en grande partie sous le niveau de la mer, entre le Mississippi et le lac Pontchartrain, protégée par des digues depuis l'ouragan Katrina. La musique live déborde chaque soir sur Frenchmen Street, sans que ce soit un événement particulier. Les funérailles jazz, menées par une fanfare, restent une tradition bien réelle. La saison des ouragans va de juin à novembre, à vérifier avant de réserver." },
    havana: { country:"Cuba", teaser:"Une ville où les voitures américaines des années 1950 restent un transport quotidien, par nécessité.", guide:"La Havane borde le détroit de Floride, le Malecón servant chaque soir de principal lieu de rassemblement social. Des décennies de restrictions ont maintenu en circulation, grâce à des réparations ingénieuses, les voitures classiques des années 1950. Le son cubain et la salsa y sont nés et se jouent en direct chaque soir dans de petits clubs. Espèces et cartes wifi dans les points publics restent la norme." },
    rio: { country:"Brésil", teaser:"Montagnes, forêt tropicale et plage tiennent dans les limites de la ville, pas en dehors.", guide:"Rio de Janeiro se glisse entre pics de granit, forêt atlantique et plages, le tout dans les limites urbaines. La vie de plage est une habitude quotidienne réelle, pas seulement de vacances, à Copacabana et Ipanema. Le Carnaval implique toute une année de répétitions dans les écoles de samba de chaque quartier. Réservez les visites de favelas auprès d'opérateurs communautaires, pas d'entreprises extérieures." },
    cartagena: { country:"Colombie", teaser:"Une ville coloniale fortifiée bâtie pour résister à des siècles de raids de pirates.", guide:"Carthagène des Indes se dresse sur la côte caraïbe, des murailles de pierre entourant encore la vieille ville, bâties contre les raids de pirates. Les palenqueras vendent des fruits tropicaux sur des plateaux portés sur la tête, héritage du village voisin de San Basilio de Palenque. La champeta, musique afro-caribéenne, anime les vraies soirées de la ville. La chaleur de midi est intense : mieux vaut marcher le matin ou en fin d'après-midi." },
    "buenos-aires": { country:"Argentine", teaser:"Une ville qui dîne à vingt-deux heures et trouve cela parfaitement normal.", guide:"Buenos Aires s'étend le long du large Rio de la Plata, avec des quartiers à forte influence européenne. Le dîner commence vraiment vers vingt-deux heures, et l'asado, barbecue lent, est presque un rituel familial hebdomadaire. Le maté, partagé entre amis avec une paille métallique, est une habitude constante tout au long de la journée. Le tango y est né et se danse vraiment dans les milongas, au-delà des spectacles pour touristes." },
    queenstown: { country:"Nouvelle-Zélande", teaser:"Une petite ville alpine qui a inventé le saut à l'élastique commercial sur un pont historique.", guide:"Queenstown borde le lac Wakatipu, cerné par la chaîne des Remarkables, sur l'île du Sud de la Nouvelle-Zélande. C'est une petite ville où la vie quotidienne s'organise autour du tourisme d'aventure, randonnée l'été, ski l'hiver. Le saut à l'élastique commercial y a été inventé, sur le pont Kawarau, toujours en activité. Le temps change vite en montagne : prévoyez toujours des couches." },
    "byron-bay": { country:"Australie", teaser:"Le point le plus oriental de l'Australie continentale, réglé sur l'horaire des vagues.", guide:"Byron Bay marque le point le plus oriental de l'Australie continentale, avec un phare d'où l'on aperçoit parfois des baleines en migration. Les conditions de surf rythment littéralement la journée d'une bonne partie des habitants. La culture bien-être et les marchés bio y sont authentiques, ancrés depuis des décennies, pas un simple argument marketing. La protection solaire compte plus qu'on ne le pense : l'indice UV y est élevé." },
    petra: { country:"Jordanie", teaser:"Toute une cité antique taillée directement dans des parois de canyon couleur rose.", guide:"Pétra se cache dans un canyon désertique, accessible par un défilé appelé le Siq, où les Nabatéens ont sculpté des façades dans le grès rose il y a plus de deux mille ans. Des communautés bédouines locales, dont certaines descendent d'habitants de Pétra elle-même, guident encore les visiteurs. Parcourir tout le site prend presque une journée entière ; des chaussures confortables sont essentielles." },
    muscat: { country:"Oman", teaser:"Une capitale qui impose à chaque nouveau bâtiment de garder les mêmes tons blancs et sable.", guide:"Mascate s'étend le long du golfe d'Oman, entre montagnes et littoral, d'anciens forts portugais toujours debout. Les règles de construction imposent des bâtiments bas aux tons blancs ou sable, donnant à la ville un aspect uniforme. L'encens brûle quotidiennement dans les maisons et les boutiques, héritage de l'ancien commerce omanais. Une tenue modeste est attendue et appréciée dans tous les lieux publics." },
    samarkand: { country:"Ouzbékistan", teaser:"Un carrefour de la route de la soie où des dômes turquoise se dressent depuis six siècles.", guide:"Samarcande occupe une plaine fertile d'Asie centrale, carrefour historique de la route de la soie entre Chine, Perse et Europe. Le Registan, place bordée de trois madrasas couvertes de céramiques turquoise, domine le centre-ville depuis plus de six cents ans. Le pain rond, appelé non, est traité avec un réel respect, jamais jeté ni posé à l'envers. Voir le Registan illuminé la nuit est une expérience différente, vivement recommandée." }
  },
  zh: {
    kyoto: { country:"日本", teaser:"一座至今仍伴着木屐声与寺庙钟声生活的城市。", guide:"京都坐落在群山之间，拥有上千座寺庙与神社，鸭川穿城而过。当地人骑车穿行于百年老宅与清晨开门的家庭小店之间。茶道与能剧在这里被发扬到极致，至今仍可拜师学习。许多寺庙和小店只收现金，出门前记得带够现金。" },
    marrakech: { country:"摩洛哥", teaser:"麦地那从不真正安静，只是卖的东西换了而已。", guide:"马拉喀什坐落在肥沃平原与阿特拉斯山脉之间，法律保护着老城赭红色的外观。家庭生活围绕里亚德庭院展开，薄荷茶几乎是一种神圣的待客仪式。杰马夫纳广场每晚都会变成露天夜市。在集市里讨价还价是被期待的对话方式，并非无礼。" },
    cusco: { country:"秘鲁", teaser:"一座印加古都，古老的石墙至今仍在承重。", guide:"库斯科坐落在安第斯山脉三千四百多米的高处，紧密拼合的印加石墙至今仍作为殖民建筑的地基。克丘亚语仍与西班牙语并用，古柯叶是当地人日常生活的一部分，而非旅游噱头。每年六月的太阳节会在人群面前重现印加仪式。建议先花一两天适应高原反应，再进行长途徒步。" },
    "cape-town": { country:"南非", teaser:"一座两大洋、一座山与一段复杂历史同时交汇的城市。", guide:"开普敦坐落在桌山脚下，两股洋流交汇让附近海滩温度差异很大。慢火烤肉聚会几乎是邻里和家人每周一次的仪式。由居民自己带领的黑人城镇游览，比海滨长廊更真实地展现这座城市。天气变化很快，记得带上保暖衣物。" },
    reykjavik: { country:"冰岛", teaser:"一座小到市长可能就在你隔壁泳道游泳的首都。", guide:"雷克雅未克依靠地热水供暖，连公共泳池都用地热水加热，是这座城市真正的社交中心。夏季几乎不落日，冬季几乎不日出。古老的萨迦故事至今仍被广泛阅读和引用。这里的自来水是世界上最干净的之一，租车能让你看到远超首都本身的风景。" },
    bali: { country:"印尼（巴厘岛）", teaser:"一个即使寺庙仪式改道交通，大家也毫不在意的小镇。", guide:"乌布四周环绕着由传统灌溉合作系统subak浇灌的梯田，由农民集体管理。每天清晨，家家户户门前都会摆上新鲜的鲜花米饭供品。从火葬到寺庙周年庆典，各种仪式随时可能封路，当地人视之为日常。进入大多数寺庙都需要穿纱笼，现场即可租借。" },
    hanoi: { country:"越南", teaser:"一座即使站着也要在小塑料凳上吃早餐的城市。", guide:"河内环绕还剑湖而建，老城区的三十六条街道至今仍以曾经售卖的行当命名。摩托车数量远超汽车，过马路时要保持稳定的步伐让司机能够预判。祖先崇拜体现在家家户户和店铺里的小神龛上。街边塑料凳小吃摊往往比隔壁的餐厅更好吃。" },
    jaipur: { country:"印度", teaser:"整座老城都按王室法令漆成同一种粉色。", guide:"斋浦尔紧邻塔尔沙漠，琥珀堡等城堡矗立山间，老城自1876年起按王室法令漆成赭粉色，至今仍受法律保护。集市按行业划分：珠宝街、纺织街、香料街，各由世代相传的家族作坊经营。拉贾斯坦邦仍保有鲜活的皇室文化，Teej等节日会让街道热闹非凡。在集市里大胆讨价还价是完全正常的。" },
    istanbul: { country:"土耳其", teaser:"唯一能在欧洲吃早餐、在亚洲吃午餐的城市。", guide:"伊斯坦布尔被博斯普鲁斯海峡实际分割在欧亚两洲之间，坐渡轮是日常通勤，而非旅游项目。郁金香形小玻璃杯里的茶水随处可见、随时供应。这座城市层叠着拜占庭与奥斯曼历史，圣索菲亚大教堂便是其中代表。乘渡轮横渡博斯普鲁斯海峡是性价比最高的体验之一。" },
    seoul: { country:"韩国", teaser:"五百年历史的宫殿与二十四小时便利文化仅一街之隔。", guide:"首尔沿汉江而建，即便市中心也能眺望到附近的群山。便利店常被当作深夜非正式咖啡馆使用，学生和上班族都常光顾。受儒家文化影响的等级观念至今仍体现在说话方式中。地铁快捷便宜，几乎人人都用，一张T-money交通卡几乎可以支付所有场景。" },
    "chiang-mai": { country:"泰国", teaser:"一座拥有三百多座寺庙、却依然从容不迫的城市。", guide:"清迈坐落在泰国北部山谷中，比曼谷更凉爽翠绿，素贴山金色寺庙从市区就能望见。这里的生活节奏明显更慢，僧侣每天清晨仍会出门化缘。兰纳文化与泰国中部截然不同，体现在独特的寺庙建筑与方言中。二月至四月是农业烧荒季节，出行前最好先查一下空气状况。" },
    lisbon: { country:"葡萄牙", teaser:"一座七丘之城，每一趟电车都是一个观景台。", guide:"里斯本建在特茹河口陡峭的山丘上，历史悠久的黄色电车至今仍是真正的公共交通工具。葡式蛋挞与浓咖啡是当地人日常习惯，并非只为游客而设。被联合国教科文组织认定的法多音乐带着淡淡忧伤，在小酒馆里演唱时全场保持安静。许多免费观景台其实比收费景点更值得一看。" },
    prague: { country:"捷克", teaser:"一座大到足以自成一座小城的城堡建筑群，至今仍在日常使用。", guide:"布拉格沿伏尔塔瓦河而建，坐拥世界上最大的古代城堡建筑群之一，至今仍是捷克总统的官邸所在。这座城市在二战轰炸中大体幸免，哥特与巴洛克风格的老城几乎完整保留至今。啤酒在许多酒吧里比瓶装水还便宜。老城清晨明显比其余时段安静许多。" },
    athens: { country:"希腊", teaser:"一座三千年历史的山丘矗立在一座依然运转的现代城市中央。", guide:"雅典坐落在群山环绕的盆地中，从几乎任何街区都能望见卫城。晚餐通常很晚才开始，很少早于晚上九点，咖啡馆常用来进行长时间的交谈。东正教复活节比圣诞节更受重视地庆祝。清晨是参观古迹、避开人群的最佳时机。" },
    edinburgh: { country:"苏格兰，英国", teaser:"一座建在火山顶上的城堡，俯瞰着建于隐藏地下街道之上的城市。", guide:"爱丁堡建在一座死火山之上，狭窄的小巷有时通向被埋在城市下方的整条街道。天气变化很快，全年都需要多层衣物。八月的爱丁堡艺穗节让整座城市变成世界上最大的艺术节。如果打算在艺穗节期间前往，请提前数月预订住宿。" },
    zanzibar: { country:"坦桑尼亚·桑给巴尔", teaser:"一个曾用雕花木门彰显家族财富的贸易港口。", guide:"石头城坐落在桑给巴尔西海岸，由珊瑚石建成的迷宫式老城，历经数百年作为印度洋贸易枢纽而形成。斯瓦希里文化融合了非洲、阿拉伯、波斯与印度的影响，体现在饮食与建筑中。雕花木门，无论是阿拉伯风格还是印度风格，至今仍标志着一个家族的历史地位。在这个以穆斯林为主的社区，着装得体会受到尊重。" },
    cairo: { country:"埃及", teaser:"千年金字塔就矗立在一座两千万人口大都市的边缘。", guide:"开罗沿尼罗河而建，吉萨金字塔如今已处于城市扩张的边缘地带。交通十分拥堵，茶馆与水烟馆是真正的日常社交场所。斋月会彻底改变这座城市的作息，白天安静，日落开斋后才热闹起来。开门时段前往金字塔可以避开酷热与人潮。" },
    accra: { country:"加纳", teaser:"一片百年古堡林立的海岸线，紧邻西非最热闹的市场之一。", guide:"阿克拉坐落在几内亚湾沿岸，殖民时期的古堡至今仍矗立在海边。马科拉市场是当地居民真正的日常购物场所，摆满了布料与食品。肯特布以其独特寓意的图案编织，至今仍在重要场合穿着，而非仅为游客而织。开口交谈前先问候一声，被视为重要的社交礼仪。" },
    oaxaca: { country:"墨西哥", teaser:"一个至今仍有十六个原住民族群塑造着日常生活的山谷。", guide:"瓦哈卡坐落在群山环绕的高原谷地中，附近就是萨波特克古城蒙特阿尔班遗址。十六个不同的原住民族群至今仍与西班牙语并用自己的语言。亡灵节在这里有着尤为深厚的意义，家庭祭坛与墓地守夜都是真实的仪式。城外小型作坊的梅斯卡尔酒品鉴，比市中心酒吧更加地道。" },
    "new-orleans": { country:"美国", teaser:"一座因地下水位过高，只能把逝者安葬在地面之上的城市。", guide:"新奥尔良大部分地区低于海平面，夹在密西西比河与庞恰特雷恩湖之间，卡特里娜飓风后由堤坝系统保护。现场音乐几乎每晚都会自然溢满弗伦奇曼街，并非什么特别活动。爵士葬礼由铜管乐队引领，至今仍是真实存在的传统。飓风季从六月持续到十一月，预订前最好先查一下。" },
    havana: { country:"古巴", teaser:"一座因现实所需，五十年代美国老爷车至今仍是日常交通工具的城市。", guide:"哈瓦那濒临佛罗里达海峡，滨海大道每天傍晚都是重要的社交聚集地。数十年的进口限制让五十年代的老爷车靠着巧妙的手工修理得以持续运转。古巴松乐与萨尔萨舞正是发源于此，每晚都在小型俱乐部现场演出。现金和公共热点购买的上网卡至今仍是常态。" },
    rio: { country:"巴西", teaser:"高山、雨林与海滩都在城市界限之内，而非之外。", guide:"里约热内卢挤身于花岗岩山峰、大西洋雨林与海滩之间，全部都在城市范围之内。海滩生活是真正的日常习惯，而非仅限假期，科帕卡巴纳和伊帕内玛都是如此。狂欢节意味着各社区桑巴学校整整一年的排练与筹备。贫民窟游览请通过社区自营的组织预订，而非外部公司。" },
    cartagena: { country:"哥伦比亚", teaser:"一座为抵御数百年海盗袭击而建的殖民城墙城市。", guide:"卡塔赫纳坐落在加勒比海岸，石砌城墙至今仍环绕着老城区，是为抵御海盗袭击而建。头顶托盘卖热带水果的女商贩，传承自附近圣巴西利奥德帕伦克村的传统。非洲加勒比风格的champeta音乐，是这座城市真实的夜生活。正午酷热难耐，最好选择清晨或傍晚出行。" },
    "buenos-aires": { country:"阿根廷", teaser:"一座晚上十点才吃晚饭、却觉得完全正常的城市。", guide:"布宜诺斯艾利斯沿宽阔的拉普拉塔河而建，各街区带有鲜明的欧洲风情。晚餐真的要到晚上十点左右才开始，慢烤烧烤几乎是每周一次的家庭仪式。马黛茶用金属吸管在朋友间传递共饮，是贯穿全天的固定习惯。探戈正是诞生于此，milonga舞厅里的真实舞蹈远胜于游客表演。" },
    queenstown: { country:"新西兰", teaser:"一座在历史悠久的桥上发明了商业蹦极的小型高山小镇。", guide:"皇后镇坐落在瓦卡蒂普湖畔，被雷马克布尔山脉环绕，位于新西兰南岛。这是一座小镇，日常生活围绕探险旅游展开，夏季徒步、冬季滑雪。商业蹦极正是在这里的卡瓦劳大桥发明，至今仍在运营。山区天气变化很快，请always准备好多层衣物。" },
    "byron-bay": { country:"澳大利亚", teaser:"澳大利亚大陆最东端，作息完全跟着浪况走。", guide:"拜伦湾标志着澳大利亚大陆的最东端，灯塔处有时能望见迁徙的鲸鱼。冲浪条件几乎决定了当地不少人一天的日程安排。这里的养生文化与有机市集是真实存在了数十年的传统，而非营销噱头。防晒比大多数人想象的更重要，这里的紫外线指数很高。" },
    petra: { country:"约旦", teaser:"整座古城直接雕刻在玫瑰色的峡谷岩壁之中。", guide:"佩特拉隐藏在沙漠峡谷之中，需穿过名为「西克」的狭窄峡道才能抵达，纳巴泰人两千多年前将立面直接雕刻进玫瑰色砂岩。当地贝都因社区，部分成员的祖先曾居住在佩特拉城内，至今仍为游客担任向导。走完整个遗址几乎需要一整天，舒适的鞋子必不可少。" },
    muscat: { country:"阿曼", teaser:"一座要求每栋新建筑都必须保持相同白色与沙色调的首都。", guide:"马斯喀特沿阿曼湾而建，坐落在山脉与海岸之间，古老的葡萄牙堡垒至今仍矗立海边。建筑法规要求建筑物低矮，色调为白色或沙色，使整座城市呈现出统一的外观。乳香每日在家中和店铺中焚烧，传承自阿曼古老的乳香贸易。在所有公共场合，得体的着装都会受到期待与尊重。" },
    samarkand: { country:"乌兹别克斯坦", teaser:"一个丝绸之路的十字路口，绿松石色圆顶已矗立六百年。", guide:"撒马尔罕坐落在中亚一片肥沃平原上，是中国、波斯与欧洲之间丝绸之路的历史交汇点。雷吉斯坦广场由三座覆满绿松石瓷砖的伊斯兰经学院环绕，六百多年来一直是这座城市的中心。名为「诺恩」的圆面包备受真诚的尊重，绝不会被扔掉或倒扣放置。夜晚灯光下的雷吉斯坦广场是截然不同、非常值得一看的体验。" }
  },
  ar: {
    kyoto: { country:"اليابان", teaser:"مدينة ما زالت تعيش على إيقاع الصنادل الخشبية وأجراس المعابد.", guide:"تقع كيوتو بين تلال تحتضن أكثر من ألف معبد وضريح، ويجري نهر كامو عبر المدينة. يتنقل السكان بالدراجات بين بيوت عمرها قرون ومحال عائلية تفتح أبوابها عند الفجر. صُقلت هنا مراسم الشاي ومسرح النو، وما زال بالإمكان تعلمهما من معلمين حقيقيين. احمل نقودًا، فكثير من المعابد والمحال الصغيرة لا تقبل البطاقات." },
    marrakech: { country:"المغرب", teaser:"المدينة القديمة لا تهدأ أبدًا حقًا، فقط يتغير ما تبيعه.", guide:"تمتد مراكش بين سهل خصيب وجبال الأطلس، ومدينتها القديمة بلون التراكوتا محمي بالقانون. تدور الحياة العائلية حول ساحات بيوت الرياض، ويكاد شاي النعناع يكون طقس ضيافة مقدسًا. تتحول ساحة جامع الفنا كل مساء إلى سوق مفتوح تحت السماء. المساومة في الأسواق حوار متوقَّع وليست وقاحة." },
    cusco: { country:"بيرو", teaser:"عاصمة إنكية ما زالت حجارتها القديمة تحمل ثقل المدينة.", guide:"ترتفع كوسكو أكثر من 3400 متر في جبال الأنديز، وجدرانها الإنكية المتراصة بإحكام لا تزال أساسًا لمبانٍ استعمارية. لا تزال لغة الكيتشوا تُتحدث إلى جانب الإسبانية، وأوراق الكوكا جزء عادي من الحياة اليومية وليست نزوة سياحية. يعيد مهرجان إنتي رايمي كل يونيو تمثيل طقس إنكي أمام الحشود. خذ يومًا أو يومين للتأقلم مع الارتفاع قبل المشي الطويل." },
    "cape-town": { country:"جنوب أفريقيا", teaser:"مدينة يلتقي فيها محيطان وجبل وتاريخ معقد في آن واحد.", guide:"تقع كيب تاون عند سفح جبل الطاولة، بين تيارين محيطيين يجعلان الشواطئ متفاوتة الحرارة كثيرًا. شواء البراي البطيء يكاد يكون طقسًا أسبوعيًا بين الجيران والعائلة. تعرض جولات الأحياء الشعبية، بقيادة سكانها أنفسهم، وجهًا أصدق للمدينة من الواجهة البحرية وحدها. الطقس يتغير بسرعة، فاحمل طبقات من الملابس." },
    reykjavik: { country:"آيسلندا", teaser:"عاصمة صغيرة لدرجة أن العمدة قد يكون في المسبح المجاور لك.", guide:"تعمل ريكيافيك بالمياه الحرارية الأرضية التي تُسخّن حتى المسابح العامة، وهي المركز الاجتماعي الحقيقي للمدينة. في الصيف لا تغرب الشمس تقريبًا، وفي الشتاء لا تشرق تقريبًا. لا تزال الحكايات الآيسلندية القديمة تُقرأ وتُقتبس بانتظام. مياه الصنبور من الأنظف في العالم، واستئجار سيارة يفتح آفاقًا أوسع بكثير من العاصمة وحدها." },
    bali: { country:"إندونيسيا (بالي)", teaser:"بلدة قد يُحوَّل فيها المرور بسبب طقس في معبد دون أن يمانع أحد.", guide:"تحيط بأوبود مدرجات أرز يرويها نظام الري التعاوني القديم المسمى سوباك، يديره المزارعون أنفسهم. تظهر قرابين جديدة من الزهور والأرز كل صباح أمام البيوت. الطقوس، من حرق الجثث إلى ذكرى المعابد، قد تُغلق شارعًا دون سابق إنذار. ارتداء الساروع إلزامي لدخول معظم المعابد." },
    hanoi: { country:"فيتنام", teaser:"مدينة تتناول الفطور على كراسٍ بلاستيكية صغيرة، وقوفًا إن لزم الأمر.", guide:"تلتف هانوي حول بحيرة هوان كييم، وشوارع حيها القديم الستة والثلاثون ما زالت تحمل أسماء الحرف التي كانت تُباع فيها. تفوق الدراجات النارية السيارات بكثير، وعبور الشارع يعني السير بخطى ثابتة يمكن للسائقين توقعها. تظهر عبادة الأجداد في مذابح صغيرة داخل البيوت والمحال. طعام الشارع على الكراسي غالبًا أفضل من المطعم المجاور." },
    jaipur: { country:"الهند", teaser:"مدينة قديمة بأكملها مطلية بنفس درجة اللون الوردي، بمرسوم ملكي.", guide:"تقع جايبور على حافة صحراء ثار، وقلاعها مثل آمبر تطل من التلال، ومدينتها القديمة مطلية باللون الوردي الطيني منذ 1876 بمرسوم ملكي ما زال ساريًا. تنقسم الأسواق حسب الحرفة: مجوهرات، نسيج، بهارات، كل منها تديره عائلات منذ أجيال. تحافظ ولاية راجستان على ثقافة ملكية حية، بمهرجانات مثل تيج تملأ الشوارع. المساومة بقوة في الأسواق أمر طبيعي تمامًا." },
    istanbul: { country:"تركيا", teaser:"المدينة الوحيدة التي يمكنك فيها تناول الفطور في أوروبا والغداء في آسيا.", guide:"تنقسم إسطنبول فعليًا بين أوروبا وآسيا عبر مضيق البوسفور، وركوب العبّارة تنقل يومي وليس رحلة سياحية. يُقدَّم الشاي باستمرار في أكواب صغيرة على شكل زهرة التوليب. تحمل المدينة طبقات بيزنطية وعثمانية، أحيانًا داخل مبنى واحد مثل آيا صوفيا. جولة بالعبّارة عبر البوسفور من أفضل التجارب وأرخصها." },
    seoul: { country:"كوريا الجنوبية", teaser:"قصور عمرها خمسمئة عام تجاور ثقافة محال مفتوحة على مدار الساعة.", guide:"تمتد سول على نهر هان، وتحيط بها جبال قريبة حتى من قلب المدينة المزدحم. تُستخدم المتاجر الصغيرة كمقاهٍ ليلية غير رسمية، يقصدها الطلاب والموظفون كثيرًا. لا يزال احترام التسلسل الهرمي المتأثر بالكونفوشيوسية يشكّل طريقة الحديث. المترو سريع ورخيص ويستخدمه الجميع تقريبًا، وبطاقة T-money تصلح لمعظم الأشياء." },
    "chiang-mai": { country:"تايلاند", teaser:"أكثر من ثلاثمئة معبد داخل مدينة ما زالت تشعر بالهدوء.", guide:"تقع تشيانغ ماي في وادٍ جبلي شمال تايلاند، أكثر برودة وخضرة من بانكوك، ومعبد دوي سوثيب الذهبي يظهر من المدينة. الحياة أبطأ بوضوح، وتقديم الصدقات للرهبان ما زال يحدث كل صباح. تظهر ثقافة لانا، المختلفة عن وسط البلاد، في عمارة المعابد واللهجة المحلية. تحقق من موسم حرق المحاصيل بين فبراير وأبريل قبل الحجز." },
    lisbon: { country:"البرتغال", teaser:"مدينة التلال السبعة حيث كل رحلة ترام هي أيضًا نقطة مشاهدة.", guide:"بُنيت لشبونة على تلال شديدة الانحدار فوق مصب نهر تاجة، وترامواتها الصفراء التاريخية ما زالت وسيلة نقل حقيقية. حلوى باستيل دي ناتا والقهوة القوية عادة يومية وليست سياحية فقط. موسيقى الفادو الحزينة، المعترف بها من اليونسكو، تُغنى في نوادٍ صغيرة يُتوقع فيها الصمت. كثير من نقاط المشاهدة المجانية أفضل من المعالم المدفوعة." },
    prague: { country:"جمهورية التشيك", teaser:"مجمّع قلعة كبير بما يكفي ليكون بلدة صغيرة بذاته، وما زال قيد الاستخدام اليومي.", guide:"تمتد براغ على نهر فلتافا، ويطل عليها أحد أكبر مجمعات القلاع القديمة في العالم، وما زال مقرًا لرئيس الجمهورية التشيكية. نجت المدينة إلى حد كبير من قصف الحرب العالمية الثانية، فبقيت بلدتها القوطية والباروكية شبه سليمة. البيرة أرخص من الماء المعبأ في كثير من الحانات. صباحات البلدة القديمة أهدأ بكثير من بقية اليوم." },
    athens: { country:"اليونان", teaser:"تلة عمرها ثلاثة آلاف عام تقف في قلب مدينة حديثة نابضة بالحياة.", guide:"تمتد أثينا في حوض تحيط به الجبال، والأكروبوليس يظهر من معظم الأحياء. تبدأ العشاء متأخرًا، نادرًا قبل التاسعة مساءً، وتُستخدم المقاهي لمحادثات طويلة. يُحتفى بعيد الفصح الأرثوذكسي بحماس أكبر من عيد الميلاد. المواقع الأثرية أقل ازدحامًا بكثير في الصباح الباكر." },
    edinburgh: { country:"اسكتلندا، المملكة المتحدة", teaser:"قلعة فوق بركان تطل على مدينة بُنيت فوق شوارع مدفونة تحت الأرض.", guide:"تقف إدنبرة على بركان خامد، وأزقتها الضيقة تخفي أحيانًا شوارع كاملة مدفونة تحت المدينة. يتغير الطقس بسرعة، فطبقات الملابس ضرورية طوال العام. يحوّل مهرجان إدنبرة فرينج في أغسطس المدينة بأكملها إلى أكبر مهرجان فني في العالم. احجز الإقامة قبل أشهر إن كنت تسافر في موسم المهرجان." },
    zanzibar: { country:"زنجبار، تنزانيا", teaser:"ميناء تجاري كانت أبوابه الخشبية المنقوشة تعلن عن ثراء العائلة.", guide:"تقع ستون تاون على ساحل زنجبار، متاهة من الحجر المرجاني بُنيت على مدى قرون كمركز تجاري في المحيط الهندي. تمزج الثقافة السواحيلية تأثيرات أفريقية وعربية وفارسية وهندية تظهر في الطعام والعمارة. الأبواب المنقوشة، عربية أو هندية الطراز، ما زالت تدل على مكانة العائلة التاريخية. اللباس المحتشم موضع تقدير في هذا المجتمع ذي الأغلبية المسلمة." },
    cairo: { country:"مصر", teaser:"أهرامات عمرها آلاف السنين على الحافة الفعلية لمدينة يسكنها عشرون مليون نسمة.", guide:"تمتد القاهرة على نهر النيل، وأهرامات الجيزة أصبحت اليوم على حافة الامتداد الحضري نفسه. حركة المرور كثيفة، ومقاهي الشاي والشيشة مراكز اجتماعية يومية حقيقية. يغيّر رمضان جدول المدينة كليًا، هادئة نهارًا ونابضة بعد الإفطار. زيارة الأهرامات عند الفتح تتجنب الحر والازدحام." },
    accra: { country:"غانا", teaser:"ساحل من الحصون العريقة يجاور بعضًا من أكثر أسواق غرب أفريقيا حيوية.", guide:"تقع أكرا على خليج غينيا، وحصون استعمارية قديمة ما زالت قائمة على الساحل. سوق ماكولا وجهة تسوق يومية حقيقية للسكان، مزدحمة بالأقمشة والطعام. قماش الكِنتي، المنسوج بأنماط ذات معانٍ محددة، ما زال يُلبس في المناسبات المهمة. التحية قبل التفاوض تُعتبر لباقة اجتماعية مهمة." },
    oaxaca: { country:"المكسيك", teaser:"واد ما زالت ست عشرة مجموعة من السكان الأصليين تشكّل حياته اليومية.", guide:"تقع واحاكا في واد مرتفع تحيط به الجبال، بالقرب من موقع مونتي ألبان الزابوتيكي القديم. ست عشرة مجموعة أصلية مختلفة ما زالت تتحدث لغاتها الخاصة إلى جانب الإسبانية. يُحتفى بعيد الموتى هنا بعمق خاص، بمذابح عائلية وسهرات في المقابر. تذوق المشروب المحلي الميزكال في مصانع صغيرة خارج المدينة أكثر أصالة من حانات وسط البلد." },
    "new-orleans": { country:"الولايات المتحدة", teaser:"مدينة تدفن موتاها فوق الأرض لأن منسوب المياه الجوفية لا يسمح بغير ذلك.", guide:"تقع نيو أورلينز في معظمها تحت مستوى سطح البحر، بين نهر المسيسيبي وبحيرة بونتشارترين، وتحميها سدود منذ إعصار كاترينا. الموسيقى الحية تفيض كل مساء في شارع فرينشمن، دون أن تكون مناسبة خاصة. جنازات الجاز، بقيادة فرقة نحاسية، ما زالت تقليدًا حقيقيًا يُمارَس. موسم الأعاصير يمتد من يونيو إلى نوفمبر، يستحق التحقق قبل الحجز." },
    havana: { country:"كوبا", teaser:"مدينة ما زالت سيارات أمريكية من الخمسينيات وسيلة نقل يومية فيها، بدافع الضرورة.", guide:"تقع هافانا على مضيق فلوريدا، ويُعد الممشى الساحلي مالكون نقطة التجمع الاجتماعي الرئيسية كل مساء. أبقت عقود من قيود الاستيراد السيارات الكلاسيكية من الخمسينيات تعمل بفضل إصلاحات منزلية بارعة. وُلدت موسيقى السون الكوبي والسالسا هنا، وتُعزف حية كل ليلة في نوادٍ صغيرة. النقد وبطاقات الإنترنت في النقاط العامة ما زالا المعتاد." },
    rio: { country:"البرازيل", teaser:"جبال وغابات مطيرة وشواطئ كلها داخل حدود المدينة، لا خارجها.", guide:"تنحشر ريو دي جانيرو بين قمم جرانيتية وغابة استوائية أطلسية وشواطئ، كلها ضمن حدود المدينة. حياة الشاطئ عادة يومية حقيقية وليست موسمية فقط، في كوباكابانا وإيبانيما. يعني الكرنفال عامًا كاملًا من التدريبات في مدارس السامبا في كل حي. احجز جولات الأحياء الشعبية عبر منظمين من المجتمع المحلي، لا شركات خارجية." },
    cartagena: { country:"كولومبيا", teaser:"مدينة استعمارية محاطة بأسوار بُنيت لتصمد أمام قرون من غارات القراصنة.", guide:"تقع كارتاخينا على الساحل الكاريبي، وأسوارها الحجرية ما زالت تحيط بالمدينة القديمة، بُنيت لصد غارات القراصنة. بائعات الفاكهة المعروفات بالبالنكيراس يبعن الفواكه الاستوائية فوق أوانٍ على رؤوسهن، إرثًا من قرية سان باسيليو دي بالنكي القريبة. موسيقى التشامبيتا الأفروكاريبية تحيي ليالي المدينة الحقيقية. حرارة الظهيرة شديدة، الأفضل المشي صباحًا أو عند الغروب." },
    "buenos-aires": { country:"الأرجنتين", teaser:"مدينة تتناول العشاء في العاشرة مساءً وتعتبر ذلك طبيعيًا تمامًا.", guide:"تمتد بوينس آيرس على نهر ريو دي لا بلاتا العريض، بأحياء ذات طابع أوروبي واضح. يبدأ العشاء فعليًا نحو الساعة العاشرة مساءً، والأسادو، الشواء البطيء، يكاد يكون طقسًا عائليًا أسبوعيًا. يُشرَب المتة، المشترك بين الأصدقاء عبر أنبوب معدني، بشكل مستمر طوال اليوم. وُلد التانغو هنا ويُرقص فعليًا في صالات الميلونغا، أبعد من العروض السياحية." },
    queenstown: { country:"نيوزيلندا", teaser:"بلدة جبلية صغيرة اخترعت القفز بالحبل المطاطي التجاري على جسر تاريخي.", guide:"تقع كوينزتاون على بحيرة واكاتيبو، محاطة بسلسلة جبال ريماركابلز، في الجزيرة الجنوبية لنيوزيلندا. إنها بلدة صغيرة تدور حياتها اليومية حول سياحة المغامرة، المشي في الصيف والتزلج في الشتاء. اختُرع القفز بالحبل المطاطي التجاري هنا على جسر كاواراو، الذي ما زال يعمل. يتغير الطقس بسرعة في الجبال، فاحمل دائمًا طبقات من الملابس." },
    "byron-bay": { country:"أستراليا", teaser:"أقصى نقطة شرقية في القارة الأسترالية، وتعمل وفق جدول الأمواج.", guide:"تمثّل بايرون باي أقصى نقطة شرقية في القارة الأسترالية، ومنارتها قد تتيح رؤية الحيتان المهاجرة أحيانًا. تحدد ظروف ركوب الأمواج جدول يوم الكثيرين هنا فعليًا. ثقافة العافية والأسواق العضوية أصيلة، متجذرة منذ عقود، لا مجرد تسويق. الحماية من الشمس أهم مما يتوقعه معظم الزوار، فمؤشر الأشعة فوق البنفسجية مرتفع هنا." },
    petra: { country:"الأردن", teaser:"مدينة قديمة بأكملها منحوتة مباشرة في جدران وادٍ ورديّة اللون.", guide:"تختبئ البتراء في وادٍ صحراوي، يُوصَل إليها عبر ممر يُدعى السيق، حيث نحت الأنباط واجهات في الحجر الرملي الوردي قبل أكثر من ألفي عام. لا تزال مجتمعات بدوية محلية، بعضها من سلالة من عاشوا داخل البتراء نفسها، ترشد الزوار. يستغرق التجول في الموقع كاملًا يومًا شبه كامل، فالحذاء المريح ضروري." },
    muscat: { country:"عُمان", teaser:"عاصمة تشترط على كل مبنى جديد الحفاظ على ذات الألوان البيضاء والرملية.", guide:"تمتد مسقط على خليج عُمان، بين الجبال والساحل، وحصون برتغالية قديمة ما زالت قائمة. تشترط أنظمة البناء مبانٍ منخفضة بألوان بيضاء أو رملية، مما يمنح المدينة مظهرًا موحدًا. يُحرق البخور يوميًا في البيوت والمحال، إرثًا من تجارة اللبان العُمانية القديمة. اللباس المحتشم متوقع ومقدَّر في جميع الأماكن العامة." },
    samarkand: { country:"أوزبكستان", teaser:"مفترق طرق على طريق الحرير، قبابه الفيروزية قائمة منذ ستة قرون.", guide:"تقع سمرقند في سهل خصيب بآسيا الوسطى، مفترق طرق تاريخي على طريق الحرير بين الصين وفارس وأوروبا. ساحة الريجستان، المحاطة بثلاث مدارس مغطاة بالبلاط الفيروزي، تتصدر مركز المدينة منذ أكثر من ستمئة عام. يُعامَل الخبز المستدير المسمى نان باحترام حقيقي، لا يُرمى أبدًا ولا يُوضع مقلوبًا. مشاهدة الريجستان مضاءً ليلًا تجربة مختلفة تستحق التخطيط لها." }
  }
};